(868, 50, 'прайс_лист', '<table class=\"table\" style=\"height: 339px;\" width=\"793\">\r\n<thead>\r\n<tr>\r\n<th></th>\r\n<th>R10-13</th>\r\n<th>R14</th>\r\n<th>R15</th>\r\n<th>R16</th>\r\n<th>R17</th>\r\n<th>R18-19</th>\r\n<th>R20</th>\r\n<th>R21+</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td scope=\"row\">Снятие и установка колеса</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Упаковка колеса в пакет</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Демонтаж шины (профилем выше 50%)</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Демонтаж шины (профилем от 50% и ниже)</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Демонтаж шины (с беспрокольной технологией RunFlat)</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Монтаж шины (профилем выше 50%)</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Балансировка колеса</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Мойка колеса (технологическая)</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n<tr>\r\n<td scope=\"row\">Пакет услуг для шин с профилем выше 50%. Cнятие и установка, демонтаж, монтаж,\r\nбалансировка, мойка, упаковка шин в пакеты) за 4 колеса.</td>\r\n<td>60</td>\r\n<td>75</td>\r\n<td>100</td>\r\n<td>120</td>\r\n<td>160</td>\r\n<td>220</td>\r\n<td>260</td>\r\n<td>290</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
